lemma isEmpty_iso_of_ne
    {k : Type u} [Field k]
    {G : Type v} [Group G]
    {ι : Type*}
    {S : ι → FDRep k G}
    (hS : FDRep.IsCompleteSetOfSimples S)
    {i j : ι}
    (hij : i ≠ j) :
    IsEmpty (S i ≅ S j)

lemma add_mem {f g : ClassFun k G}
    (hf : f ∈ C_Z k G) (hg : g ∈ C_Z k G) :
    f + g ∈ C_Z k G

lemma mul_mem {f g : ClassFun k G}
    (hf : f ∈ C_Z k G) (hg : g ∈ C_Z k G) :
    f * g ∈ C_Z k G

lemma neg_mem {f : ClassFun k G}
    (hf : f ∈ C_Z k G) :
    -f ∈ C_Z k G

lemma pow_mem {f : ClassFun k G}
    (hf : f ∈ ClassFun.C_Z k G) :
    ∀ n : ℕ, f ^ n ∈ ClassFun.C_Z k G

lemma sub_mem {f g : ClassFun k G}
    (hf : f ∈ C_Z k G) (hg : g ∈ C_Z k G) :
    f - g ∈ C_Z k G

lemma zsmul_mem (n : ℤ) {f : ClassFun k G}
    (hf : f ∈ C_Z k G) :
    n • f ∈ C_Z k G

lemma isOfFinOrder [Fact p.Prime] {a : G}
    (h : IsPRegular p a) :
    IsOfFinOrder a

lemma isOfFinOrder [Fact p.Prime] {a : G}
    (h : IsPSingular p a) :
    IsOfFinOrder a

lemma orderOf_dvd_ordProj [Fact p.Prime] {a : G} (h : IsPSingular p a) {n : ℕ}
    (hd : orderOf a ∣ n) (hn : n ≠ 0) :
    orderOf a ∣ ordProj[p] n

lemma induction_mem
    {H : Subgroup G}
    {ψ : ClassFun k H}
    (hψ :
      ψ ∈ BrauerSpanChar (G := H)) :
    ClassFun.ind H ψ ∈ BrauerSpanChar

lemma induction_mem
    {H : Subgroup G}
    {P : Subgroup H → Prop}
    {Q : Subgroup G → Prop}
    (hmap : ∀ K : Subgroup H, P K → Q (K.map H.subtype))
    {ψ : ClassFun k H}
    (hψ : ψ ∈ InducedCharacterSpan P) :
    ClassFun.ind H ψ ∈ InducedCharacterSpan Q

lemma induction_mem
    {H : Subgroup G}
    {φ : ClassFun k H}
    (hφ : φ ∈ PElementarySpanChar p) :
    ClassFun.ind H φ ∈ PElementarySpanChar p
